<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title><?=e($quote['code'])?></title><style>
*{box-sizing:border-box}body{font-family:DejaVu Sans,Arial,sans-serif;font-size:11px;color:#203041;margin:34px 40px;line-height:1.55}.head{display:flex;justify-content:space-between;border-bottom:3px solid #245342;padding-bottom:18px;margin-bottom:25px}.logo{font-size:25px;letter-spacing:2px;font-weight:800;color:#1d4d3b}.logo em{color:#58a27b;font-style:normal}.muted{color:#6d7c8a}.box{padding:13px 17px;background:#f3f7f5;border:1px solid #dfe9e3;border-radius:6px;margin:16px 0}.two{width:100%;margin-bottom:19px}.two td{width:50%;vertical-align:top}h1{font-size:20px;margin:10px 0 3px;color:#1a4034}h2{font-size:13px;margin-top:24px;color:#274c40}table.lines{width:100%;border-collapse:collapse;margin-top:12px}table.lines th{text-align:left;background:#e9f1ec;color:#325b49}table.lines th,table.lines td{padding:10px 9px;border-bottom:1px solid #dce8e1}table.lines th:last-child,table.lines td:last-child{text-align:right}.totals{width:290px;margin:18px 0 20px auto;border-collapse:collapse}.totals td{padding:5px}.totals td:last-child{text-align:right}.grand{border-top:2px solid #315c4a;font-weight:bold;font-size:15px;color:#1a4938}.foot{margin-top:50px;border-top:1px solid #d4e2da;padding-top:12px;color:#708077;font-size:9px}.status{font-weight:bold;color:#527e68}
</style></head><body>
<div class="head"><div><div class="logo">AURORA<em>.</em></div><div class="muted">Marcenaria Aurora · Empresa fictícia</div></div><div style="text-align:right"><strong>PROPOSTA COMERCIAL</strong><br><span class="muted"><?=e($quote['code'])?></span></div></div>
<h1><?=e($quote['title'])?></h1><div class="muted">Emitida em <?=e(date_br($quote['created_at']))?> &nbsp; | &nbsp; Validade: <?=e(date_br($quote['valid_until']))?></div>
<table class="two"><tr><td><div class="box"><strong>CLIENTE</strong><br><?=e($quote['customer_name'])?><br><?=e($quote['document'])?><br><?=e($quote['phone'])?><br><?=e($quote['email'])?></div></td><td><div class="box"><strong>DETALHES</strong><br>Proposta: <?=e($quote['code'])?><br>Projeto: <?=e($quote['project_title']??'A definir')?><br>Status: <span class="status"><?=e(label_status($quote['status']))?></span></div></td></tr></table>
<h2>Itens incluídos na proposta</h2><table class="lines"><thead><tr><th>Item / Material</th><th>Quantidade</th><th>Unidade</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['description'])?></td><td><?=e(qty($i['quantity']))?></td><td><?=e($i['unit'])?></td></tr><?php endforeach;?></tbody></table>
<?php $calc=quote_total($items,(float)$quote['labor_cost'],(float)$quote['markup_pct'],(float)$quote['tax_pct'],(float)$quote['discount']);?>
<table class="totals"><tr><td>Produtos e serviços</td><td><?=e(money($calc['sale']))?></td></tr><tr><td>Tributos estimados</td><td><?=e(money($calc['tax']))?></td></tr><tr><td>Desconto concedido</td><td>− <?=e(money($quote['discount']))?></td></tr><tr class="grand"><td>TOTAL DA PROPOSTA</td><td><?=e(money($quote['total']))?></td></tr></table>
<?php if($quote['notes']):?><h2>Condições e observações</h2><p><?=nl2br(e($quote['notes']))?></p><?php endif;?><div class="foot">Documento de demonstração · Dados de empresa fictícia. Sem valor fiscal. Orçamento sujeito a confirmação de medidas e condições comerciais.</div>
